UPDATE courses SET
    course_description = '<div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-64253bb7 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="64253bb7" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>The <b>Bachelor of Business (BBus)</b> is a 24 subject, 3-year undergraduate degree. The course is designed to provide graduates with the knowledge and skills to function in a broad range of business environments. In accord with The Institute of International Studies (TIIS) strategic vision, graduates from the Bachelor of Business will be professionally orientated and work ready. The course fulfils the requirements of CPA (Australia) and the Chartered Accountants Association of Australia and New Zealand (CAANZ).</p> </div> </div> <div class="elementor-element elementor-element-1fe8378 elementor-widget__width-initial elementor-widget elementor-widget-image" data-e-type="widget" data-element_type="widget" data-id="1fe8378" data-widget_type="image.default"> <div class="elementor-widget-container"> <img alt="" class="attachment-large size-large wp-image-992244" decoding="async" height="100" src="https://www.tiis.edu.au/wp-content/uploads/2023/11/CPA-1.png" width="300"/> </div> </div> <div class="elementor-element elementor-element-15b95fc elementor-widget__width-initial elementor-widget elementor-widget-image" data-e-type="widget" data-element_type="widget" data-id="15b95fc" data-widget_type="image.default"> <div class="elementor-widget-container"> <img alt="" class="attachment-large size-large wp-image-992246" decoding="async" height="100" loading="lazy" src="https://www.tiis.edu.au/wp-content/uploads/2023/11/CAAUNZ-logo-1.png" width="139"/> </div> </div> <div class="elementor-element elementor-element-18bceaad elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="18bceaad" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Overview</h3> </div> </div> <div class="elementor-element elementor-element-19237226 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="19237226" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>The Bachelor of Business program at TIIS not only equips graduates with academic knowledge<br/>but also instils practical skills and a forward-thinking mindset, ensuring they are well-prepared<br/>for the complexities of the modern business landscape.</p> </div> </div> <div class="elementor-element elementor-element-3820d099 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="3820d099" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Careers</h3> </div> </div> <div class="elementor-element elementor-element-3dd0546 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="3dd0546" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <ul><li>Management Consultant</li><li>Marketing Manager</li><li>Entrepreneur</li><li>Human Resource Manager</li></ul> </div> </div> <div class="elementor-element elementor-element-471967d5 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="471967d5" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Learning Outcomes</h3> </div> </div> <div class="elementor-element elementor-element-5c02984e elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="5c02984e" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Knowledge</strong></p><p>Business Communication: Acquire practical communication skills vital for professional interactions, including business writing, presentation techniques, and intercultural communication.</p><p>Business Ethics and Sustainability: Understand the ethical dimensions of business operations and the importance of sustainable practices.</p><p>Business Statistics and Research: Develop proficiency in statistical analysis and research<br/>methodologies crucial for informed decision-making.</p><p>Enterprise Design and Value Creation: Learn to design and create value within the business<br/>context, fostering innovative thinking.</p> </div> </div> <div class="elementor-element elementor-element-c1858ab elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="c1858ab" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Skills</strong></p><p>Critical Thinking: Cultivate the ability to analyze information, assess situations, and make informed decisions.</p><p>Team Collaboration: Hone collaboration skills essential for effective teamwork within organizational settings.</p><p>Entrepreneurial Mindset: Foster an entrepreneurial spirit, enabling graduates to identify and seize<br/>business opportunities.</p><p>Strategic Management: Develop skills to formulate and implement strategic plans for organizational success.</p><p>Global Business Understanding: Gain insights into the global business environment, preparing<br/>for diverse international contexts.</p> </div> </div> </div>',
    total_course_duration = '3 Years',
    offshore_tuition_fee = 52800,
    enrolment_fee = 300,
    materials_fee = 0,
    entry_requirements = '<div class="entry-requirements-container"> <div class="academic-requirements"> <div class="elementor-element elementor-element-7fac020 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="7fac020" data-widget_type="text-editor.default" id="entry2"> <div class="elementor-widget-container"> <h5><strong>Undergraduate Programs</strong></h5><ul><li>Completion of the NSW Higher School Certificate (or equivalent) achieving an ATAR of at least 50 (or equivalent) for BBusand at least 60 (or equivalent) for BIT within the past two years; or</li><li>Completion of an AQF 5 Diploma level program from TAFE (or equivalent) or any Australian Registered TrainingOrganisation (or equivalent overseas organisation); or</li><li>Completion of at least one semester of full-time study (or part-time equivalent) at a registered Australian higher educationprovider at AQF Level 5 Diploma or higher; or</li><li>Completion of a bridging or enabling course from a qualified Australian provider (or equivalent overseas provider) andachieved at least 50% of the maximum mark attainable.</li></ul> </div> </div> </div> <div class="english-requirements"> <div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-6d694e4 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="6d694e4" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none"}'' data-widget_type="heading.default" id="english-proficiency"> <div class="elementor-widget-container"> <h1 class="elementor-heading-title elementor-size-default">English Proficiency</h1> </div> </div> <div class="elementor-element elementor-element-313b394 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="313b394" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>International students whose first language is not English must demonstrate competency in the English language. English proficiency can be demonstrated by providing evidence of an International English Language Testing System (IELTS) overall test result (or equivalent alternative test result – such as TOEFL (Test of English as a Foreign Language) or PTE (Pearson Tests of English) – as defined by regulation) that meets the specified level of English proficiency required for the course.</p> </div> </div> <div class="elementor-element elementor-element-86b695d elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="86b695d" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>In our current courses:</p><p> </p><table><tbody><tr><td width="100"><p><strong>Courses</strong></p></td><td width="100"><p><strong>IELTS Overall</strong></p></td><td width="100"><p><strong>Minimum Band (IELTS)</strong></p></td><td width="100"><p><strong>PTE Overall</strong></p></td><td width="100"><p><strong>Minimum Score (PTE)</strong></p></td></tr><tr><td width="100"><p>Undergraduate Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 5.5</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 42</p></td></tr><tr><td width="100"><p>Graduate Certificate &amp; Graduate Diploma Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 50</p></td></tr><tr><td width="100"><p>Master’s Programs</p></td><td width="100"><p>6.5</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>58</p></td><td width="100"><p>No score lower than 50</p></td></tr></tbody></table> </div> </div> </div> </div> </div>',
    apply_form = 'https://www.tiis.edu.au/bachelor-of-business-bbus/',
    updated_at = NOW()
WHERE cricos_course_code = '107616A';
