UPDATE courses SET
    course_description = '<div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-64253bb7 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="64253bb7" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>The <strong>Graduate Certificate in Business Administration (GCBA)</strong> is a 4 subject postgraduate award designed for students to gain advanced knowledge and skills in core business areas. Conceptually, the GCBA has been developed to provide graduates with the capacity to operate within a narrower range of business environments. It is also envisioned that the course will provide business knowledge to newly promoted managers in other industries and fields. Graduates will gain a range of important management related skills.</p> </div> </div> <div class="elementor-element elementor-element-18bceaad elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="18bceaad" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Overview</h3> </div> </div> <div class="elementor-element elementor-element-19237226 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="19237226" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>The Graduate Certificate in Business Administration empowers graduates to navigate and effectively manage the intricacies of contemporary business challenges. This program instils a comprehensive understanding of fundamental business principles, equipping professionals with the skills to confidently lead the evolving business landscape.</p> </div> </div> <div class="elementor-element elementor-element-471967d5 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="471967d5" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Learning Outcomes</h3> </div> </div> <div class="elementor-element elementor-element-5c02984e elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="5c02984e" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Knowledge</strong></p><p><span style="font-weight: 400;">Consolidate foundational theories and materials both conceptually and practically from accounting, management leadership, ethics, economics, and marketing.</span></p> </div> </div> <div class="elementor-element elementor-element-c1858ab elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="c1858ab" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Skills</strong></p><p><span style="font-weight: 400;">Critically evaluate key management theories and apply them in various business contexts.</span></p><p><span style="font-weight: 400;">Utilize knowledge to identify and implement effective solutions.</span></p><p><span style="font-weight: 400;">Integrate program competencies conceptually and practically.</span></p><p><span style="font-weight: 400;">Communicate theoretical aspects of management administration within curriculum constraints.</span></p><p><span style="font-weight: 400;">Interpret and effectively communicate complex business administration information to selected audiences.</span></p> </div> </div> <div class="elementor-element elementor-element-4c9d40b elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="4c9d40b" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Learning Pathways</strong></p><p><span style="font-weight: 400;">Students who successfully complete the GCBA will be eligible to enroll in the MBA at TIIS. Students may also be interested in transferring to other awards. TIIS academic staff will provide guidance for interested students.</span></p> </div> </div> <div class="elementor-element elementor-element-d1d4bbb elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="d1d4bbb" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Programme</h3> </div> </div> <div class="elementor-element elementor-element-a12ea99 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="a12ea99" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Course Design and Structure</strong></p><p>The subjects and sequence for the Graduate Certificate in Business Administration are outlined below. Students will complete 4 compulsory core subjects, each of 6 credit points in value.</p> </div> </div> </div>',
    total_course_duration = '0.5 Years',
    offshore_tuition_fee = 10000,
    enrolment_fee = 300,
    materials_fee = 0,
    entry_requirements = '<div class="entry-requirements-container"> <div class="academic-requirements"> <div class="elementor-element elementor-element-ce9cdc0 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="ce9cdc0" data-widget_type="text-editor.default" id="entry1"> <div class="elementor-widget-container"> <h5><strong>Postgraduate Programs</strong></h5><div><p><strong>General entry requirements for Master’s Programs:</strong></p><ul><li>Completion of an undergraduate degree from a recognised Australian institution (or equivalent overseas institution); or</li><li>Completion of a relevant graduate certificate or diploma from a recognised Australian institution (or equivalent overseasinstitution).</li></ul><p><strong>General entry requirements for Graduate Certificate Programs:</strong></p><ul><li>Completion of an undergraduate degree from a recognised Australian institution (or equivalent overseas institution); or</li><li>TAFE (or equivalent institution) Diploma or Advanced Diploma in a related field and three years relevant work experience inthe past five years.</li></ul></div> </div> </div> </div> <div class="english-requirements"> <div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-6d694e4 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="6d694e4" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none"}'' data-widget_type="heading.default" id="english-proficiency"> <div class="elementor-widget-container"> <h1 class="elementor-heading-title elementor-size-default">English Proficiency</h1> </div> </div> <div class="elementor-element elementor-element-313b394 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="313b394" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>International students whose first language is not English must demonstrate competency in the English language. English proficiency can be demonstrated by providing evidence of an International English Language Testing System (IELTS) overall test result (or equivalent alternative test result – such as TOEFL (Test of English as a Foreign Language) or PTE (Pearson Tests of English) – as defined by regulation) that meets the specified level of English proficiency required for the course.</p> </div> </div> <div class="elementor-element elementor-element-86b695d elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="86b695d" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>In our current courses:</p><p> </p><table><tbody><tr><td width="100"><p><strong>Courses</strong></p></td><td width="100"><p><strong>IELTS Overall</strong></p></td><td width="100"><p><strong>Minimum Band (IELTS)</strong></p></td><td width="100"><p><strong>PTE Overall</strong></p></td><td width="100"><p><strong>Minimum Score (PTE)</strong></p></td></tr><tr><td width="100"><p>Undergraduate Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 5.5</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 42</p></td></tr><tr><td width="100"><p>Graduate Certificate &amp; Graduate Diploma Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 50</p></td></tr><tr><td width="100"><p>Master’s Programs</p></td><td width="100"><p>6.5</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>58</p></td><td width="100"><p>No score lower than 50</p></td></tr></tbody></table> </div> </div> </div> </div> </div>',
    apply_form = 'https://www.tiis.edu.au/graduate-certificate-in-business-administration/',
    updated_at = NOW()
WHERE cricos_course_code = '107618K';
UPDATE courses SET
    course_description = '<div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-64253bb7 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="64253bb7" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>The<b> Graduate Certificate in Professional Accounting (GCPA)</b> has been designed as a stand-alone accounting qualification or a PATHWAY to the MPA and accreditation with all the major professional bodies. The subjects have been aligned with the first four subjects of the MPAA program. Students have the option to either continue on to the MPAA or graduate with the GCPA after completing the four subjects.</p> </div> </div> <div class="elementor-element elementor-element-18bceaad elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="18bceaad" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Overview</h3> </div> </div> <div class="elementor-element elementor-element-19237226 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="19237226" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><span style="font-weight: 400;">The Graduate Certificate in Professional Accounting (GCPA) is a concise program within the MPAA, delivered over two academic blocks, comprising four specialized units. It is an entry or exit qualification, providing graduates with focused expertise for specific business contexts. The program addresses essential topics, such as Accounting Principles, Business and Company Law, Economics for Business, and Business Finance. GCPA is a pathway program for those requiring entry-level qualification adjustments within the MPA framework.</span></p> </div> </div> <div class="elementor-element elementor-element-3820d099 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="3820d099" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Careers</h3> </div> </div> <div class="elementor-element elementor-element-3dd0546 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="3dd0546" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <ul><li><p><span style="font-weight: 400;">Accounting Assistant</span></p></li><li><p><span style="font-weight: 400;">Junior Financial Analyst</span></p></li><li><p><span style="font-weight: 400;">Bookkeeping Clerk</span></p></li><li><p><span style="font-weight: 400;">Accounts Payable/Receivable Clerk</span></p></li><li><p><span style="font-weight: 400;">Tax Preparation Assistant</span></p></li></ul> </div> </div> <div class="elementor-element elementor-element-471967d5 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="471967d5" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Learning Outcomes</h3> </div> </div> <div class="elementor-element elementor-element-5c02984e elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="5c02984e" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Knowledge</strong></p><p>Deep understanding of financial accounting principles and practices.</p><p>Proficiency in Australian legal and taxation frameworks.</p><p>Advanced knowledge of business finance, corporate accounting, and auditing principles.</p><p>In-depth grasp of management accounting, business statistics, and contemporary accounting theory.</p> </div> </div> <div class="elementor-element elementor-element-c1858ab elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="c1858ab" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Skills</strong></p><p><span style="font-weight: 400;">Critical evaluation of theoretical, legal, and ethical frameworks shaping professional accounting and business practices.</span></p><p><span style="font-weight: 400;">Application of knowledge to synthesize data for effective problem-solving.</span></p><p><span style="font-weight: 400;">Systematic investigation of data, challenging biases for robust decision-making.</span></p><p><span style="font-weight: 400;">Effective interpretation and communication of accounting information using diverse methodologies.</span></p><p><span style="font-weight: 400;">Examination of contemporary issues, contributing judgment and insight to decision-making in professional practice.</span></p> </div> </div> </div>',
    total_course_duration = '0.5 Years',
    offshore_tuition_fee = 10000,
    enrolment_fee = 300,
    materials_fee = 0,
    entry_requirements = '<div class="entry-requirements-container"> <div class="academic-requirements"> <div class="elementor-element elementor-element-ce9cdc0 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="ce9cdc0" data-widget_type="text-editor.default" id="entry1"> <div class="elementor-widget-container"> <h5><strong>Postgraduate Programs</strong></h5><div><p><strong>General entry requirements for Master’s Programs:</strong></p><ul><li>Completion of an undergraduate degree from a recognised Australian institution (or equivalent overseas institution); or</li><li>Completion of a relevant graduate certificate or diploma from a recognised Australian institution (or equivalent overseasinstitution).</li></ul><p><strong>General entry requirements for Graduate Certificate Programs:</strong></p><ul><li>Completion of an undergraduate degree from a recognised Australian institution (or equivalent overseas institution); or</li><li>TAFE (or equivalent institution) Diploma or Advanced Diploma in a related field and three years relevant work experience inthe past five years.</li></ul></div> </div> </div> </div> <div class="english-requirements"> <div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-6d694e4 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="6d694e4" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none"}'' data-widget_type="heading.default" id="english-proficiency"> <div class="elementor-widget-container"> <h1 class="elementor-heading-title elementor-size-default">English Proficiency</h1> </div> </div> <div class="elementor-element elementor-element-313b394 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="313b394" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>International students whose first language is not English must demonstrate competency in the English language. English proficiency can be demonstrated by providing evidence of an International English Language Testing System (IELTS) overall test result (or equivalent alternative test result – such as TOEFL (Test of English as a Foreign Language) or PTE (Pearson Tests of English) – as defined by regulation) that meets the specified level of English proficiency required for the course.</p> </div> </div> <div class="elementor-element elementor-element-86b695d elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="86b695d" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>In our current courses:</p><p> </p><table><tbody><tr><td width="100"><p><strong>Courses</strong></p></td><td width="100"><p><strong>IELTS Overall</strong></p></td><td width="100"><p><strong>Minimum Band (IELTS)</strong></p></td><td width="100"><p><strong>PTE Overall</strong></p></td><td width="100"><p><strong>Minimum Score (PTE)</strong></p></td></tr><tr><td width="100"><p>Undergraduate Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 5.5</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 42</p></td></tr><tr><td width="100"><p>Graduate Certificate &amp; Graduate Diploma Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 50</p></td></tr><tr><td width="100"><p>Master’s Programs</p></td><td width="100"><p>6.5</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>58</p></td><td width="100"><p>No score lower than 50</p></td></tr></tbody></table> </div> </div> </div> </div> </div>',
    apply_form = 'https://www.tiis.edu.au/graduate-certificate-in-professional-accounting/',
    updated_at = NOW()
WHERE cricos_course_code = '097841A';
