UPDATE courses SET
    course_description = '<div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-64253bb7 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="64253bb7" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>The <b>Master of Business Administration (MBA)</b> prepares graduates to identify, delineate and manage complex challenges faced by organisations in the current and future business environment. Consistent with the professional nature of graduate business program environments, it prepares graduates for memberships in affiliated associations.</p> </div> </div> <div class="elementor-element elementor-element-18bceaad elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="18bceaad" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Overview</h3> </div> </div> <div class="elementor-element elementor-element-19237226 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="19237226" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> The Master of Business Administration (MBA) at TIIS is strategically designed for professionals aiming to excel in today''s dynamic business arena. This program goes beyond traditional business education, focusing on real-world challenges and fostering skills crucial for leadership in a rapidly evolving global landscape. Enrolling in this program provides an opportunity to elevate careers and become a dynamic force in the contemporary business environment. </div> </div> <div class="elementor-element elementor-element-3820d099 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="3820d099" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Careers</h3> </div> </div> <div class="elementor-element elementor-element-3dd0546 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="3dd0546" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <ul><li>Business Consultant</li><li>Strategic Manager</li><li>Marketing Director</li><li>Operations Manager</li><li>Entrepreneur</li></ul> </div> </div> <div class="elementor-element elementor-element-471967d5 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="471967d5" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Learning Outcomes</h3> </div> </div> <div class="elementor-element elementor-element-5c02984e elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="5c02984e" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Knowledge</strong></p><p>Understand the complexities of managing people, resources, and capital in today’s evolving business and socio-political environment.</p><p>Consolidate key principles in strategic planning, marketing, management accounting, information systems, and business law.</p><p>Demonstrate applied research skills in quantitative and qualitative research methods.</p> </div> </div> <div class="elementor-element elementor-element-c1858ab elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="c1858ab" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Skills</strong></p><p>Critically evaluate theoretical, social, legislative, and ethical frameworks shaping business governance.</p><p>Apply business knowledge to formulate cost-effective solutions to routine and complex issues.</p><p>Undertake systematic investigations to build robust business information and decision-making systems.</p><p>Interpret and effectively communicate business intelligence, governance issues, and systems to diverse audiences.</p><p>Analyze contemporary issues through business management perspectives, methodologies, and<br/>theoretical knowledge, showcasing judgment and informed decision-making.</p> </div> </div> <div class="elementor-element elementor-element-4c9d40b elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="4c9d40b" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Application of Knowledge and Skills</strong></p><p>Provide expert advice from various sources for informed business decision-making.</p><p>Generate alternate management scenarios using analytic tools and diverse perspectives.</p><p>Plan and execute a substantial research-based project on a contemporary business theme.</p><p>Apply leadership, communication, and interpersonal skills across various business settings.</p><p>Engage in continuous learning and reflection, fostering new insights into professional practice.</p> </div> </div> </div>',
    total_course_duration = '2 Years',
    offshore_tuition_fee = 40000,
    enrolment_fee = 300,
    materials_fee = 0,
    entry_requirements = '<div class="entry-requirements-container"> <div class="academic-requirements"> <div class="elementor-element elementor-element-ce9cdc0 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="ce9cdc0" data-widget_type="text-editor.default" id="entry1"> <div class="elementor-widget-container"> <h5><strong>Postgraduate Programs</strong></h5><div><p><strong>General entry requirements for Master’s Programs:</strong></p><ul><li>Completion of an undergraduate degree from a recognised Australian institution (or equivalent overseas institution); or</li><li>Completion of a relevant graduate certificate or diploma from a recognised Australian institution (or equivalent overseasinstitution).</li></ul><p><strong>General entry requirements for Graduate Certificate Programs:</strong></p><ul><li>Completion of an undergraduate degree from a recognised Australian institution (or equivalent overseas institution); or</li><li>TAFE (or equivalent institution) Diploma or Advanced Diploma in a related field and three years relevant work experience inthe past five years.</li></ul></div> </div> </div> </div> <div class="english-requirements"> <div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-6d694e4 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="6d694e4" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none"}'' data-widget_type="heading.default" id="english-proficiency"> <div class="elementor-widget-container"> <h1 class="elementor-heading-title elementor-size-default">English Proficiency</h1> </div> </div> <div class="elementor-element elementor-element-313b394 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="313b394" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>International students whose first language is not English must demonstrate competency in the English language. English proficiency can be demonstrated by providing evidence of an International English Language Testing System (IELTS) overall test result (or equivalent alternative test result – such as TOEFL (Test of English as a Foreign Language) or PTE (Pearson Tests of English) – as defined by regulation) that meets the specified level of English proficiency required for the course.</p> </div> </div> <div class="elementor-element elementor-element-86b695d elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="86b695d" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>In our current courses:</p><p> </p><table><tbody><tr><td width="100"><p><strong>Courses</strong></p></td><td width="100"><p><strong>IELTS Overall</strong></p></td><td width="100"><p><strong>Minimum Band (IELTS)</strong></p></td><td width="100"><p><strong>PTE Overall</strong></p></td><td width="100"><p><strong>Minimum Score (PTE)</strong></p></td></tr><tr><td width="100"><p>Undergraduate Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 5.5</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 42</p></td></tr><tr><td width="100"><p>Graduate Certificate &amp; Graduate Diploma Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 50</p></td></tr><tr><td width="100"><p>Master’s Programs</p></td><td width="100"><p>6.5</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>58</p></td><td width="100"><p>No score lower than 50</p></td></tr></tbody></table> </div> </div> </div> </div> </div>',
    apply_form = 'https://www.tiis.edu.au/master-of-business-administration/',
    updated_at = NOW()
WHERE cricos_course_code = '107617M';
UPDATE courses SET
    course_description = '<div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-64253bb7 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="64253bb7" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>The <strong>Master of Professional Accounting (Advanced) (MPAA)</strong> is professionally accredited by CPA Australia, Chartered Accountants Australia and New Zealand (CA ANZ), and the Association of Chartered Certified Accountants (ACCA).</p><p>Successful completion of the MPAA satisfies the academic requirements for entry into the CPA Program and the Chartered Accountants Program, subject to the admission requirements and policies of the respective professional bodies. The program is also accredited by ACCA, enabling eligible graduates to apply for exemptions from selected ACCA examinations in accordance with ACCA’s accreditation and exemption policies.</p><p>The MPAA is designed to equip graduates with the technical knowledge, professional skills, ethical understanding, and analytical capabilities required for successful careers in accounting, auditing, taxation, business advisory, finance, and related professions.</p> </div> </div> <div class="elementor-element elementor-element-00c6dca e-grid e-con-boxed e-con e-parent" data-e-type="container" data-element_type="container" data-id="00c6dca"> <div class="e-con-inner"> <div class="elementor-element elementor-element-561c751 elementor-widget elementor-widget-image" data-e-type="widget" data-element_type="widget" data-id="561c751" data-widget_type="image.default"> <div class="elementor-widget-container"> <img alt="" class="attachment-large size-large wp-image-997589" decoding="async" height="438" sizes="(max-width: 1000px) 100vw, 1000px" src="https://www.tiis.edu.au/wp-content/uploads/2026/06/public-practice-cpa-australia-logo.jpg" srcset="https://www.tiis.edu.au/wp-content/uploads/2026/06/public-practice-cpa-australia-logo.jpg 1000w, https://www.tiis.edu.au/wp-content/uploads/2026/06/public-practice-cpa-australia-logo-300x131.jpg 300w, https://www.tiis.edu.au/wp-content/uploads/2026/06/public-practice-cpa-australia-logo-768x336.jpg 768w" width="1000"/> </div> </div> <div class="elementor-element elementor-element-c2b9f2d elementor-widget elementor-widget-image" data-e-type="widget" data-element_type="widget" data-id="c2b9f2d" data-widget_type="image.default"> <div class="elementor-widget-container"> <img alt="" class="attachment-large size-large wp-image-997590" decoding="async" height="471" loading="lazy" sizes="(max-width: 1024px) 100vw, 1024px" src="https://www.tiis.edu.au/wp-content/uploads/2026/06/CAANZ_Logo_Horizontal_Full_RGB-1024x471.png" srcset="https://www.tiis.edu.au/wp-content/uploads/2026/06/CAANZ_Logo_Horizontal_Full_RGB-1024x471.png 1024w, https://www.tiis.edu.au/wp-content/uploads/2026/06/CAANZ_Logo_Horizontal_Full_RGB-300x138.png 300w, https://www.tiis.edu.au/wp-content/uploads/2026/06/CAANZ_Logo_Horizontal_Full_RGB-768x353.png 768w, https://www.tiis.edu.au/wp-content/uploads/2026/06/CAANZ_Logo_Horizontal_Full_RGB-1536x707.png 1536w, https://www.tiis.edu.au/wp-content/uploads/2026/06/CAANZ_Logo_Horizontal_Full_RGB.png 1737w" width="1024"/> </div> </div> <div class="elementor-element elementor-element-047fb16 elementor-widget elementor-widget-image" data-e-type="widget" data-element_type="widget" data-id="047fb16" data-widget_type="image.default"> <div class="elementor-widget-container"> <img alt="" class="attachment-large size-large wp-image-997609" decoding="async" height="365" loading="lazy" sizes="(max-width: 746px) 100vw, 746px" src="https://www.tiis.edu.au/wp-content/uploads/2026/06/acca-final.png" srcset="https://www.tiis.edu.au/wp-content/uploads/2026/06/acca-final.png 746w, https://www.tiis.edu.au/wp-content/uploads/2026/06/acca-final-300x147.png 300w" width="746"/> </div> </div> </div> </div> <div class="elementor-element elementor-element-18bceaad elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="18bceaad" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Overview</h3> </div> </div> <div class="elementor-element elementor-element-19237226 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="19237226" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> The Master of Professional Accounting (Advanced) at TIIS is a program consisting of 16 prescribed units of study, providing an in-depth exploration of accounting principles, business law, economics, finance, information systems, and more. With a carefully sequenced program, students acquire advanced knowledge, practical skills, and real-world applications in various contexts within the accounting field. </div> </div> <div class="elementor-element elementor-element-3820d099 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="3820d099" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Careers</h3> </div> </div> <div class="elementor-element elementor-element-3dd0546 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="3dd0546" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <ul><li><p><span style="font-weight: 400;">Accountant </span></p></li><li><p><span style="font-weight: 400;">Management Consultant</span></p></li><li><p><span style="font-weight: 400;">Risk Management Specialist</span></p></li><li><p><span style="font-weight: 400;">Financial Analyst</span></p></li><li><p><span style="font-weight: 400;">Audit and Assurance Specialist</span></p></li><li><p><span style="font-weight: 400;">Business Finance Consultant</span></p></li><li><p><span style="font-weight: 400;">Financial Systems Analyst</span></p></li></ul> </div> </div> <div class="elementor-element elementor-element-471967d5 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="471967d5" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none","_animation_delay":100}'' data-widget_type="heading.default"> <div class="elementor-widget-container"> <h3 class="elementor-heading-title elementor-size-default">Learning Outcomes</h3> </div> </div> <div class="elementor-element elementor-element-5c02984e elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="5c02984e" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Knowledge</strong></p><p><span style="font-weight: 400;">Core business and accounting knowledge, encompassing principles and methods for researching existing and emerging issues within the field.</span></p><p><span style="font-weight: 400;">The capacity for continuous learning through the integration of new ideas, precepts, and applications.</span></p> </div> </div> <div class="elementor-element elementor-element-c1858ab elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="c1858ab" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p><strong>Skills</strong></p><p><span style="font-weight: 400;">Critically evaluate key theoretical, social, legislative, professional, legal, and ethical frameworks influencing professional accounting and business practices.</span></p><p><span style="font-weight: 400;">Apply their knowledge of accounting and business systems to synthesize data and develop responses to both routine and complex problems.</span></p><p><span style="font-weight: 400;">Undertake systematic investigations of data, including re-examining basic principles and challenging common biases to build robust information and decision-making systems.</span></p><p><span style="font-weight: 400;">Interpret and effectively communicate accounting and business information to the intended audience, drawing on a range of tools and methodologies.</span></p><p><span style="font-weight: 400;">Examine contemporary issues by integrating professional accounting and business technical skills, research methodologies, and theoretical knowledge, showcasing the capacity to exercise judgment, contribute to professional practice, and aid in decision-making.</span></p><p><span style="font-weight: 400;">Demonstrate the capacity to generate appropriate research-related responses to contemporary accounting and business problems.</span></p> </div> </div> </div>',
    total_course_duration = '1.5 Years',
    offshore_tuition_fee = 30000,
    enrolment_fee = 300,
    materials_fee = 0,
    entry_requirements = '<div class="entry-requirements-container"> <div class="academic-requirements"> <div class="elementor-element elementor-element-ce9cdc0 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="ce9cdc0" data-widget_type="text-editor.default" id="entry1"> <div class="elementor-widget-container"> <h5><strong>Postgraduate Programs</strong></h5><div><p><strong>General entry requirements for Master’s Programs:</strong></p><ul><li>Completion of an undergraduate degree from a recognised Australian institution (or equivalent overseas institution); or</li><li>Completion of a relevant graduate certificate or diploma from a recognised Australian institution (or equivalent overseasinstitution).</li></ul><p><strong>General entry requirements for Graduate Certificate Programs:</strong></p><ul><li>Completion of an undergraduate degree from a recognised Australian institution (or equivalent overseas institution); or</li><li>TAFE (or equivalent institution) Diploma or Advanced Diploma in a related field and three years relevant work experience inthe past five years.</li></ul></div> </div> </div> </div> <div class="english-requirements"> <div class="elementor-widget-wrap elementor-element-populated"> <div class="elementor-element elementor-element-6d694e4 elementor-invisible elementor-widget elementor-widget-heading" data-e-type="widget" data-element_type="widget" data-id="6d694e4" data-settings=''{"_animation":"fadeIn","_animation_tablet":"none","_animation_mobile":"none"}'' data-widget_type="heading.default" id="english-proficiency"> <div class="elementor-widget-container"> <h1 class="elementor-heading-title elementor-size-default">English Proficiency</h1> </div> </div> <div class="elementor-element elementor-element-313b394 elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="313b394" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>International students whose first language is not English must demonstrate competency in the English language. English proficiency can be demonstrated by providing evidence of an International English Language Testing System (IELTS) overall test result (or equivalent alternative test result – such as TOEFL (Test of English as a Foreign Language) or PTE (Pearson Tests of English) – as defined by regulation) that meets the specified level of English proficiency required for the course.</p> </div> </div> <div class="elementor-element elementor-element-86b695d elementor-widget elementor-widget-text-editor" data-e-type="widget" data-element_type="widget" data-id="86b695d" data-widget_type="text-editor.default"> <div class="elementor-widget-container"> <p>In our current courses:</p><p> </p><table><tbody><tr><td width="100"><p><strong>Courses</strong></p></td><td width="100"><p><strong>IELTS Overall</strong></p></td><td width="100"><p><strong>Minimum Band (IELTS)</strong></p></td><td width="100"><p><strong>PTE Overall</strong></p></td><td width="100"><p><strong>Minimum Score (PTE)</strong></p></td></tr><tr><td width="100"><p>Undergraduate Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 5.5</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 42</p></td></tr><tr><td width="100"><p>Graduate Certificate &amp; Graduate Diploma Programs</p></td><td width="100"><p>6.0</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>50</p></td><td width="100"><p>No score lower than 50</p></td></tr><tr><td width="100"><p>Master’s Programs</p></td><td width="100"><p>6.5</p></td><td width="100"><p>No band below 6.0</p></td><td width="100"><p>58</p></td><td width="100"><p>No score lower than 50</p></td></tr></tbody></table> </div> </div> </div> </div> </div>',
    apply_form = 'https://www.tiis.edu.au/master-of-professional-accounting/',
    updated_at = NOW()
WHERE cricos_course_code = '097840B';
